/* Illustrative planning model, not a product calculation or financial advice. */
const reportingDeals=[
 {name:'Office equipment proposal',stage:'Decision',owner:'Sales lead',value:400000,probability:.75,close:20,receipt:50,action:'Confirm the decision date'},
 {name:'Branch supply agreement',stage:'Proposal',owner:'Account manager',value:300000,probability:.5,close:45,receipt:75,action:'Follow up: no activity in 8 days'},
 {name:'Training programme',stage:'Proposal',owner:'Sales lead',value:200000,probability:.5,close:70,receipt:100,action:'Confirm scope and payment terms'},
 {name:'Service renewal',stage:'Decision',owner:'Customer success',value:100000,probability:.5,close:15,receipt:25,action:'Check renewal requirements'}
];
const reportingMoney=n=>'J$'+n.toLocaleString('en-JM');
function reportingTotals(days){return {revenue:reportingDeals.filter(d=>d.close<=days).reduce((s,d)=>s+d.value*d.probability,0),receipts:reportingDeals.filter(d=>d.receipt<=days).reduce((s,d)=>s+d.value*d.probability,0)};}
function reportingPeriod(days){
 const t=reportingTotals(days);
 const later=reportingDeals.filter(d=>d.close<=days&&d.receipt>days);
 const gap=t.revenue-t.receipts;
 const explanation=later.map(d=>`The ${d.name.toLowerCase()} adds ${reportingMoney(d.value*d.probability)} to the sales forecast (${reportingMoney(d.value)} × a ${d.probability*100}% assumed chance of winning). The sale is assumed to close on <b>day ${d.close}</b>, but payment is assumed on <b>day ${d.receipt}</b>, outside this ${days}-day window.`).join(' ');
 return `<div class="rf-number"><span>Sales forecast</span><strong>${reportingMoney(t.revenue)}</strong><small>Deals closing within ${days} days</small></div><div class="rf-number rf-number-cash"><span>Cash receipt forecast</span><strong>${reportingMoney(t.receipts)}</strong><small>Payments arriving within ${days} days</small></div><p class="rf-weighting-note"><b>Illustrative, probability-weighted estimates.</b> Both totals use deal value × assumed chance of winning. Neither is confirmed sales or money already received.</p><div class="rf-period-insight"><b>Why is the cash estimate ${reportingMoney(gap)} lower?</b><p>${explanation}</p><p class="rf-takeaway"><b>Before planning spending, check when customers may pay.</b></p></div>`;
}
pages.reporting=()=>`<section class="rf-hero"><div class="wrap"><div><a class="breadcrumb" href="#/platform">AyudaGrow / Reporting & forecasting</a><span class="eyebrow">From sales activity to management decisions</span><h1>See where you stand.<br><em>Plan what comes next.</em></h1><p>Bring pipeline stages, opportunity values and next actions into view. Then look ahead at expected sales and potential cash inflows, with the assumptions clear.</p><div class="actions"><a class="button" href="#/contact">Build a clearer business view <span>→</span></a><button class="textlink rf-jump" type="button" data-reporting-jump>Explore the example ↓</button></div></div><div class="rf-hero-board"><div class="rf-board-heading"><b>Management view</b><span>ILLUSTRATIVE</span></div><div class="rf-hero-metrics"><div><small>Open pipeline</small><strong>J$1,000,000</strong><span>4 sample opportunities</span></div><div><small>Needs attention</small><strong>1</strong><span>No activity in 8 days</span></div></div><div class="rf-mini-chart" aria-label="Sample weighted sales value: 350,000 Jamaican dollars within 30 days, 500,000 within 60 days and 600,000 within 90 days"><span style="--rf-bar:81.667px"><b>J$350k</b><i></i><small>30 days</small></span><span style="--rf-bar:116.667px"><b>J$500k</b><i></i><small>60 days</small></span><span style="--rf-bar:140px"><b>J$600k</b><i></i><small>90 days</small></span></div><p>Weighted sales value · cumulative horizons</p><div class="rf-board-bottom">A useful signal. <b>A human decision.</b></div></div></div></section>`+
section(`<div class="section-head"><div><span class="eyebrow">Understand today</span><h2>A pipeline with a story.<br>Not just a total.</h2></div><p>See where opportunities stand, what they may be worth, who owns them and the next action. A large total means little if the dates are stale or nobody is following up.</p></div><div class="rf-pipeline">${[['Qualified enquiry','Understand the need','Value and fit still being confirmed'],['Proposal','Make the offer clear','Scope, amount and expected decision date'],['Decision','Keep the next step visible','Owner, last activity and follow-up'],['Won / lost','Record the outcome','Learn what converted and why']].map(([h,p,s],i)=>`<article><span>0${i+1}</span><h3>${h}</h3><b>${p}</b><p>${s}</p></article>`).join('')}</div><p class="micro">Illustrative stage definitions. Configure your pipeline around how you sell; stage names alone do not establish a deal’s probability.</p>`)+
section(`<div id="rf-example" class="section-head"><div><span class="eyebrow">Explore a management planning example</span><h2>A sale can close<br>before the customer pays.</h2></div><p>Compare when deals may close with when payments may arrive. Choose 30, 60 or 90 days. All figures are fictional Jamaican dollars, not AyudaGrow results or customer financial data.</p></div><div class="rf-controls" role="group" aria-label="Select cumulative forecast horizon">${[30,60,90].map(n=>`<button type="button" data-reporting-days="${n}" aria-pressed="${n===30}" aria-controls="rf-period">Within ${n} days</button>`).join('')}</div><div class="rf-period" id="rf-period" aria-live="polite">${reportingPeriod(30)}</div><p class="micro">Each horizon starts today. The 60-day figure includes the first 30 days; do not add the three figures together. This teaching model is not a replica of a configured product dashboard.</p><details class="rf-method"><summary>See the sample records and calculation assumptions</summary><p>For this illustration only, weighted value = opportunity value × an assumed probability. Sales enter the view by the expected close day; potential receipts use a separate assumed payment day. The same weighting is used for receipts solely to explain the timing difference, not to predict individual customer payments.</p><div class="rf-deals">${reportingDeals.map(d=>`<article><h3>${d.name}</h3><p>${reportingMoney(d.value)} × ${d.probability*100}% = <b>${reportingMoney(d.value*d.probability)}</b></p><dl><div><dt>Stage</dt><dd>${d.stage}</dd></div><div><dt>Owner</dt><dd>${d.owner}</dd></div><div><dt>Expected close</dt><dd>Day ${d.close}</dd></div><div><dt>Assumed receipt</dt><dd>Day ${d.receipt}</dd></div></dl><small>${d.action}</small></article>`).join('')}</div><p>No tax, costs, partial payments, opening cash balance or collection-risk model is included. These figures are not a net cash-flow forecast or accounting revenue recognition.</p></details>`,'rf-example-section')+
section(`<div class="section-head"><div><span class="eyebrow">From dashboard to decision</span><h2>The number is the start.<br>The next action matters.</h2></div><p>Use a shared view to ask better questions before making commitments. In this example, a Jamaican supplier reviews the pipeline with the team at the start of the week.</p></div><div class="rf-decisions">${[
['01 / FOLLOW-UP','A J$300,000 proposal has gone quiet.','The record shows no activity in eight days.','Ask the account manager to check the buyer’s status, record the next step and revise the expected close date if needed.'],
['02 / STAFFING','Possible work is building for the next quarter.','The 90-day weighted sales estimate is J$600,000.','Review delivery dates and team capacity. Explore staffing options alongside signed work and downside scenarios before making a hiring commitment.'],
['03 / PURCHASING','Expected sales arrive before some payments.','By day 30, estimated sales are J$350,000 but potential receipts are J$50,000.','Check deposits, supplier terms and existing cash before ordering stock. A likely sale does not fund a purchase until cash is available.'],
['04 / TARGETS','The outlook is below the planning target.','J$600,000 expected against a fictional J$700,000 90-day sales target leaves a J$100,000 gap.','Review conversion, slipping deals and new opportunities. Adjust the plan rather than treating the target as a promised result.']
].map(([k,h,s,a])=>`<article><span class="eyebrow">${k}</span><h3>${h}</h3><div class="rf-signal"><small>THE SIGNAL</small><p>${s}</p></div><div class="rf-action"><small>THE MANAGEMENT RESPONSE</small><p>${a}</p></div></article>`).join('')}</div>`)+
section(`<div class="rf-quality"><div><span class="eyebrow">Better records. More useful conversations.</span><h2>A forecast is only<br>as useful as its inputs.</h2><p>Keep opportunity values, owners, stages, probabilities and expected dates current. Agree what the numbers mean and review the underlying deals, not just the chart.</p><p>For potential cash inflows, payment terms and receipt timing matter too. If those details are missing, show the gap instead of presenting a precise-looking answer.</p><a class="textlink" href="#/crm">Explore the CRM foundation →</a></div><ol><li><b>Define</b><span>Agree stages, values, reporting periods and what counts as a conversion.</span></li><li><b>Maintain</b><span>Update close dates and next actions. Remove duplicate or no-longer-active opportunities.</span></li><li><b>Compare</b><span>Review forecast versus actual outcomes and understand where assumptions were wrong.</span></li><li><b>Act</b><span>Assign follow-up, revisit probabilities and bring meaningful changes into the next review.</span></li></ol></div>`,'how')+
section(`<div class="section-head"><div><span class="eyebrow">A wider view of performance</span><h2>Know what is happening.<br>Learn what is working.</h2></div><p>Choose reports that answer a real management question, using the data your team actually captures.</p></div>${cardList([['Pipeline & opportunity value','Review stages, owners and amounts. Separate total open value from weighted expectations and won opportunities.'],['Conversion & lead sources','Compare how enquiries progress by source and stage. Use consistent definitions and complete attribution before deciding which channels work best.'],['Appointments & activity','Review bookings, attendance and follow-through where these are captured and configured. Identify gaps in the process before blaming the people.'],['Selected planning periods','Agree useful horizons, such as 30, 60 and 90 days, where the configured reports and data support them. Use date filters and source records consistently.']])}`)+
section(`<div class="rf-limits"><span class="eyebrow">Know the limits before you rely on the view</span><h2>Planning support.<br>Not a financial guarantee.</h2><p>Forecasts are estimates based on available CRM and sales information. They are not audited accounting projections, guaranteed revenue, guaranteed cash flow or a substitute for your financial records and professional judgment.</p><p>The 30/60/90-day cash-inflow illustration requires receipt-timing assumptions beyond a sales close date. A ready-made cash forecast, bank integration or accounting integration is not promised here. Confirm the available data, calculation method, reports and any additional configuration before activation.</p><p>Opportunity forecasting can use time-based views and weighted values. Account availability, settings and exact calculations still need verification for your setup.</p><a href="#/contact" class="textlink">Discuss reporting setup with AyudaGrow →</a></div>`,'rf-limits-section')+
section(`<div class="rf-next"><div><span class="eyebrow">Start with the decisions you need to make</span><h2>What would a clearer<br>view help you decide?</h2><p>Bring your pipeline, management questions and reporting needs. We’ll agree a useful starting view, the information it needs and a practical review routine.</p></div><a href="#/contact" class="button blue">Talk through your reporting <span>→</span></a></div>${linkCards([['crm','THE FOUNDATION','Keep the opportunity current.','Values, owners, stages and next actions in one shared process.'],['follow-up','THE FOLLOW-THROUGH','Act on what needs attention.','Turn the review into a clear next step for the right person.']])}`);
const reportingPriorWiring=wireExpanded;wireExpanded=function(){reportingPriorWiring();document.querySelector('[data-reporting-jump]')?.addEventListener('click',()=>document.getElementById('rf-example').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));document.querySelectorAll('[data-reporting-days]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-reporting-days]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('rf-period').innerHTML=reportingPeriod(Number(b.dataset.reportingDays));}));};
render();
